@Test
void 프록시_여부() {
    em.clear();
    Member a = queryFactory.selectFrom(member)
            .join(member.team, team)
            .where(member.username.eq("m1")).fetchOne();
    System.out.println("페치 없이: " + a.getTeam().getClass().getSimpleName());

    em.clear();
    Member b = queryFactory.selectFrom(member)
            .join(member.team, team).fetchJoin()
            .where(member.username.eq("m1")).fetchOne();
    System.out.println("페치 있고: " + b.getTeam().getClass().getSimpleName());
}

