                .leftJoin(member.team, team).fetchJoin()
                .limit(5)
                .fetch();
        members.forEach(m -> {
            if (m.getTeam() != null) m.getTeam().getMembers().size();
        });
    });
    System.out.println("쿼리 " + n + "개");
}

